return [{
  json: {
    gcp_project: 'tmdatabase',
    bq_dataset: 'dm_base_crm',
    config_dataset: 'tmdatabase.dm_daily_brief',
    timezone: 'Asia/Ho_Chi_Minh',
    thresholds: {
      kpi_normal_band_pct: 20,
      warning_drop_pct: 20,
      warning_zero_lead_days: 5,
      warning_pending_days: 3,
      warning_pending_min_count: 5,
      warning_open_deal_days: 14,
      warning_open_deal_min: 5,
      cvr_drop_pp: 5,
      focus_positive_pct: 15,
      focus_negative_pct: -15,
      min_base_volume: 3,
      unmapped_alert_min: 1
    },
    limits: {
      top_course_per_bu: 5,
      top_utm_rows: 8,
      top_utm_rows_weekly: 12,
      max_warning_rows: 12
    },
    openai_model: 'gpt-4.1'
  }
}];

function vnParts(d) {
  const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short' });
  const parts = fmt.formatToParts(d);
  const get = (t) => parts.find(p => p.type === t).value;
  return { y: get('year'), m: get('month'), d: get('day'), weekday: get('weekday') };
}
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const now = new Date();
const todayVN = vnParts(now);
const weekdayMap = { Mon: 2, Tue: 3, Wed: 4, Thu: 5, Fri: 6, Sat: 7, Sun: 0 };
const reportDay = weekdayMap[todayVN.weekday];
const isSaturday = todayVN.weekday === 'Sat';
const yesterdayDate = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const yVN = vnParts(yesterdayDate);
const reportDate = yVN.y + '-' + yVN.m + '-' + yVN.d;
const dayNames = { 2: 'Thu Hai', 3: 'Thu Ba', 4: 'Thu Tu', 5: 'Thu Nam', 6: 'Thu Sau', 7: 'Thu Bay' };
const focusTitles = {
  2: 'MARKETING DAY 1 ALERT',
  3: 'MARKETING DAY 2 & BRAND ALERT',
  4: 'EXECUTIVE EDUCATION ALERT',
  5: 'DATA SCHOOL ALERT',
  6: 'TM AI ALERT',
  7: 'FLEXIBLE COMBO & B2B TRAINING ALERT'
};
return [{
  json: {
    run_id: uuidv4(),
    report_date: reportDate,
    report_day: reportDay,
    is_saturday: isSaturday,
    weekday_label: dayNames[reportDay] || '',
    focus_title: focusTitles[reportDay] || ''
  }
}];

const cfg = $('Config').first().json;
const rd = $('Resolve Day').first().json;
const q0 = $('Q0 Data Health').all().map(i => i.json);
const q1 = $('Q1 KPI').first() ? $('Q1 KPI').first().json : {};
const q2 = $('Q2 Breakdown').all().map(i => i.json);
const q3 = $('Q3 UTM Daily').all().map(i => i.json);
const q4 = $('Q4 No-Lead Courses').all().map(i => i.json);
const q5raw = $('Q5 Warning Scan').all().map(i => i.json);
const q6 = $('Q6 Focus Group').all().map(i => i.json);

let q7 = [];
let q3weekly = [];
if (rd.is_saturday) {
  q7 = $('Q7 Weekly Review').all().map(i => i.json);
  q3weekly = $('Q3b UTM Weekly').all().map(i => i.json);
}

function countFlags(row) {
  return ['flag_lead_drop', 'flag_deal_drop', 'flag_no_lead', 'flag_pending', 'flag_stale_open']
    .reduce((n, k) => n + (row[k] ? 1 : 0), 0);
}
const q5 = q5raw
  .filter(r => countFlags(r) > 0)
  .sort((a, b) => countFlags(b) - countFlags(a))
  .slice(0, cfg.limits.max_warning_rows);

const unmapped_total = q0.reduce((s, r) => s + Number(r.n || 0), 0);
const data_health = {
  unmapped_total,
  show_alert: unmapped_total >= cfg.thresholds.unmapped_alert_min,
  rows: q0
};

return [{
  json: {
    run_id: rd.run_id,
    report_date: rd.report_date,
    weekday_label: rd.weekday_label,
    focus_title: rd.focus_title,
    is_saturday: rd.is_saturday,
    kpi: q1,
    breakdown: q2,
    utm_daily: q3,
    utm_weekly: q3weekly,
    no_lead_courses: q4,
    warnings: q5,
    focus_group: q6,
    weekly_review: q7,
    data_health
  }
}];

